// Full schema. Returns XML, not JSON - opts.headers asks for it explicitly.
const r = await api.get(env.baseUrl + '/$metadata', undefined, {
  headers: { Accept: 'application/xml' },
});
const xml = typeof r.data === 'string' ? r.data : JSON.stringify(r.data);
console.log('status', r.status, 'chars', xml.length);
const types = [...xml.matchAll(/<EntityType Name="([^"]+)"/g)].map((m) => m[1]);
const enums = [...xml.matchAll(/<EnumType Name="([^"]+)"/g)].map((m) => m[1]);
console.log('entity types:', types.length, types.join(', '));
console.log('enum types:', enums.length, enums.join(', '));
