// $filter literal syntax: strings single-quoted, guids bare, dates unquoted
// ISO-8601, enums fully qualified. Verified working on this service.
const cases = {
  'contains email':      "contains(Email,'@gmail.com')",
  'startswith name':     "startswith(DisplayName,'a')",
  'active + approved':   'IsActive eq true and IsApproved eq true',
  'never logged in':     'LastLoginAt eq null',
  'created this year':   'CreatedAt ge 2026-01-01T00:00:00Z',
  'not deleted':         'IsDeleted eq false',
  'lambda any on scopes': 'UserRoleScopes/any(s:s/IsSharingEnabled eq true)',
  'tolower match':       "tolower(LoginType) eq 'email'",
};

for (const [label, filter] of Object.entries(cases)) {
  const r = await api.get(q('Users', { '$filter': filter, '$top': 1, '$count': 'true', '$select': 'Id,Email' }));
  console.log(String(r.status), String(r.data['@odata.count']).padStart(5), label, '::', filter);
}

