// A collection response is one page. Follow @odata.nextLink until it is
// absent - do not rebuild paging with $skip when a nextLink was given.
// Server page size here is 100.
let url = q('Users', { '$select': 'Id,Email', '$count': 'true' });
let page = 0;
let seen = 0;
let total = null;

while (url && page < 5) {
  const r = await api.get(url);
  if (total === null) total = r.data['@odata.count'];
  seen += r.data.value.length;
  page += 1;
  console.log('page', page, '+' + r.data.value.length, 'rows, running total', seen, 'of', total);
  url = r.data['@odata.nextLink'] || null;
}
console.log(url ? 'stopped at the 5-page guard, more pages remain' : 'reached the last page');

