  '$select': 'Id,RoleName,IsSystemRole,OrganizationId',
  '$expand': 'RolePermissions($filter=IsDeleted eq false;$expand=Permission($select=PermissionName,DisplayName)),Organization($select=Name)',
  '$filter': 'IsDeleted eq false',
  '$orderby': 'RoleName',
  '$top': 5,
  '$count': 'true',
}));
console.log('status', r.status, 'roles', r.data['@odata.count']);
for (const role of r.data.value) {
  const perms = (role.RolePermissions || []).map((rp) => rp.Permission?.PermissionName).filter(Boolean);
  console.log(role.RoleName, '| system', role.IsSystemRole, '| org', role.Organization?.Name ?? '(global)');
  console.log('   perms:', perms.length ? perms.join(', ') : '(none)');
}

