// ---- OData helper (query options must be URL-encoded, not the $ names) ----
const q = (set, opts = {}) => {
  const s = Object.entries(opts)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => k + '=' + encodeURIComponent(String(v)))
    .join('&');
  return env.baseUrl + '/' + set + (s ? '?' + s : '');
};

